const prompt = String($input || '');
const answer = String((typeof $answer === 'undefined' || $answer === null) ? '' : $answer);
const result = await screen([{ role: 'user', content: prompt }, { role: 'assistant', content: answer }]);
if (result.verdict === 'allowed') {
  return answer;
}
